(function(root){
'use strict';
const STORE='vestkyst-save-v1';
const ambitions={
 coast:{title:'Et navn på vestkysten',short:'Bygg et nettverk som folk blir i.',requirements:'Tre Stavanger-områder, ferdigutviklet Bergen med rivalpress under 60 og minst 60 lojalitet.'},
 country:{title:'Hele kartet',short:'La Stavanger bli begynnelsen.',requirements:'Alle fem byer, fire ferdigutviklede utposter med rivalpress under 60, 100 innflytelse og fullført nasjonalt prosjekt.'},
 exit:{title:'Gå hjem med noe igjen',short:'Bygg en vei ut før 2036.',requirements:'12 millioner i kassa, høyst 25 søkelys, åtte fullførte kvartalsavtaler og fullført etterfølgelsesprosjekt.'}
};
const html=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function alias(value){return Array.from(String(value||'').normalize('NFC').replace(/[\u0000-\u001f\u007f]/g,'').replace(/\s+/g,' ').trim()).slice(0,24).join('')||'Skipperen';}
function classifyRaw(raw,game){if(raw===null)return {kind:'fresh'};try{const parsed=JSON.parse(raw);return game.valid(parsed)?{kind:'valid',state:parsed}:{kind:'recovery'};}catch(_){return {kind:'recovery'};}}
function configure(game,options={}){const next=game.fresh();next.name=alias(options.alias);next.goal=Object.hasOwn(ambitions,options.goal)?options.goal:'coast';if(options.seed!==undefined){if(!Number.isInteger(options.seed)||options.seed<0||options.seed>4294967295)throw Error('Ugyldig startfrø.');game.seedCampaign(next,options.seed);}if(!game.valid(next))throw Error('Den nye runden kunne ikke klargjøres.');return next;}
function commitFresh(storage,key,expectedRaw,game,options={}){try{
 if(storage.getItem(key)!==expectedRaw)return {ok:false,reason:'changed',message:'En annen fane har lagret en runde. Last inn på nytt før du velger videre.'};
 if(expectedRaw!==null&&!options.allowReplace)return {ok:false,reason:'protected',message:'Den eksisterende lagringen er bevart. Bekreft en ny runde først.'};
 const next=configure(game,options);storage.setItem(key,JSON.stringify(next));return {ok:true,state:next};
 }catch(_){return {ok:false,reason:'storage',message:'Nettleseren lot oss ikke lagre. Ingen eksisterende runde er erstattet. Sjekk nettleserinnstillingene og prøv igjen.'};}}
const api={sanitizeAlias:alias,escape:html,classifyRaw,configure,commitFresh,ambitions};root.VestkystOnboarding=api;
if(typeof module!=='undefined')module.exports=api;
if(typeof document==='undefined'||typeof s==='undefined')return;
const game=root.Game;let originalRaw,storage;
try{storage=root.localStorage;originalRaw=storage.getItem(STORE);}catch(_){originalRaw=null;}
const classification=classifyRaw(originalRaw,game);if(classification.kind==='valid')return;
const ui={mode:classification.kind==='fresh'?'intro':'recovery',step:0,alias:'',goal:'coast',sound:false,replace:false,error:'',busy:false};
const panel=document.createElement('section');panel.id='vestkyst-onboarding';panel.className='ob-shell';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','Velkommen til Vestkyst');
const shell=document.querySelector('.game-shell'),oldHidden=shell?.getAttribute('aria-hidden');if(shell){shell.inert=true;shell.setAttribute('aria-hidden','true');}document.body.append(panel);document.body.classList.add('onboarding-open');
if(typeof exUI!=='undefined')exUI.sound=false;
api.isActive=()=>panel.isConnected;
function focus(selector){panel.querySelector(selector)?.focus({preventScroll:true});}
function draw(target){
 if(ui.mode==='recovery'){panel.innerHTML=`<div class="ob-recovery"><span class="ob-eyebrow">HISTORIEN DIN ER BEVART</span><h1>Lagringen trenger<br>en hånd.</h1><p>Vi kunne ikke åpne runden som ligger i denne nettleseren. Originalen er urørt. Du kan ta vare på filen eller importere en sikkerhetskopi.</p><div class="ob-recovery-actions"><button class="button brass" data-ob="export">Last ned originalfilen ↗</button><button class="button ghost" data-ob="settings">Åpne lagringsinnstillinger</button><button class="text-button" data-ob="reload">Last inn på nytt</button></div><p class="ob-alert" role="alert">${html(ui.error)}</p><button class="text-button ob-replace" data-ob="replace">Jeg vil starte en ny runde…</button><small>Ingen konto. Lagringen finnes bare på denne enheten.</small></div>`;focus('[data-ob="export"]');return;}
 const a=ambitions[ui.goal];panel.innerHTML=`<div class="ob-welcome"><div class="ob-picture" role="img" aria-label="Regn over kaien i Stavanger"><a class="ob-logo" href="#" tabindex="-1">VESTKYST<span>BYEN GLEMMER IKKJE.</span></a><div class="ob-picture-caption"><span>STAVANGER / 2026 — 2036</span><strong>Små gater.<br>Lange minner.</strong></div></div><div class="ob-content"><div class="ob-progress" aria-label="Steg ${ui.step+1} av 2"><i class="${ui.step===0?'active':''}"></i><i class="${ui.step===1?'active':''}"></i><span>${ui.step+1} / 2</span></div>${ui.step===0?`<span class="ob-eyebrow">DET BEGYNNE PÅ KAIEN</span><h1>Ka skal byen<br>kalla deg?</h1><p class="ob-lead">8 000 kroner. Ingen ansatte. Et helt tiår å sette spor i.</p><label class="ob-alias-label" for="ob-alias">Ditt alias <span>Ikke det fulle navnet ditt.</span></label><input id="ob-alias" name="alias" maxlength="24" autocomplete="off" spellcheck="false" placeholder="Skipperen" value="${html(ui.alias)}"><fieldset class="ob-ambitions"><legend>Velg en retning <span>Du kan endre den underveis.</span></legend>${Object.entries(ambitions).map(([id,v])=>`<button type="button" data-ob-goal="${id}" class="${id===ui.goal?'chosen':''}" aria-pressed="${id===ui.goal}"><span class="ob-choice-dot" aria-hidden="true"></span><span><b>${html(v.title)}</b><small>${html(v.short)}</small></span></button>`).join('')}</fieldset><p class="ob-requirements"><b>Målet i 2036:</b> ${html(a.requirements)}</p><button class="button brass ob-primary" data-ob="next">Møt Raggen →</button><button class="text-button ob-skip" data-ob="skip">Hopp over · start med standardvalg</button>`:`<span class="ob-eyebrow">EN KJENT PÅ STORHAUG</span><h1>Javel,<br>${html(alias(ui.alias))}.</h1><div class="ob-raggen">${typeof G!=='undefined'&&G.contactPortrait?G.contactPortrait('raggen'):typeof portrait==='function'?portrait(0):'<span aria-hidden="true">R</span>'}<div><span>RAGGEN</span><blockquote>«Et navn e greit. Nå må du finna ut kem du vil vera når någen trenge deg.»</blockquote></div></div><div class="ob-first-tip"><span>DITT FØRSTE TREKK</span><h2>Begynn lite. Bli kjent.</h2><p>Ta en prat med Raggen på Storhaug, eller planlegg et lite innkjøp. Du ser varekostnad, reise og risiko før du bestemmer deg. Folk og faste ruter bygger du opp etter hvert.</p></div><label class="ob-sound"><input id="ob-sound" type="checkbox" ${ui.sound?'checked':''}> Diskret lyd ved egne valg <small>Valgfritt. Ingen musikk.</small></label><p class="ob-local">Runden lagres i denne nettleseren. Ingen konto, ingen registrering.</p><button class="button brass ob-primary" data-ob="start">Start på kaien →</button><button class="text-button ob-skip" data-ob="back">← Tilbake til navnet</button>`}<p class="ob-alert" role="alert">${html(ui.error)}</p></div></div>`;
 focus(target||(ui.step===0?'#ob-alias':'[data-ob="start"]'));
}
function close(){panel.remove();document.body.classList.remove('onboarding-open');if(shell){shell.inert=false;if(oldHidden===null)shell.removeAttribute('aria-hidden');else shell.setAttribute('aria-hidden',oldHidden);}}
function exportOriginal(){if(originalRaw===null)return;const link=document.createElement('a'),url=URL.createObjectURL(new Blob([originalRaw],{type:'application/json'}));link.href=url;link.download='vestkyst-original-lagring.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function firstMove(){const screen=document.querySelector('#screen');if(!screen)return;const tip=document.createElement('aside');tip.className='ob-guidance';tip.setAttribute('aria-label','Raggens første tips');tip.innerHTML='<div><span>RAGGEN HAR ET TIPS</span><b>Du velger første trekk.</b><p>Se kostnaden for en liten reise, eller møt kontaktene på Storhaug.</p></div><button class="button ghost" data-ob-guidance="travel">Se første reise →</button><button class="text-button" data-ob-guidance="close" aria-label="Lukk første tips">×</button>';screen.prepend(tip);tip.addEventListener('click',e=>{const b=e.target.closest('[data-ob-guidance]');if(!b)return;if(b.dataset.obGuidance==='travel'&&typeof countries==='function')countries();tip.remove();});}
function start(defaults=false){if(ui.busy)return;ui.busy=true;let seed;try{if(root.crypto?.getRandomValues)seed=root.crypto.getRandomValues(new Uint32Array(1))[0];}catch(_){}
 const result=commitFresh(storage,STORE,originalRaw,game,{alias:defaults?'Skipperen':ui.alias,goal:defaults?'coast':ui.goal,seed,allowReplace:ui.replace});ui.busy=false;if(!result.ok){ui.error=result.message;draw();return;}
 s=result.state;view='home';const sound=defaults?false:ui.sound;if(typeof exUI!=='undefined')exUI.sound=sound;try{storage.setItem('vestkyst-sound',sound?'on':'off');}catch(_){}close();render();firstMove();document.querySelector('#screen')?.scrollIntoView({block:'start',behavior:'auto'});
}
function recoverySettings(){const button=document.querySelector('#settings');button?.onclick?.call(button);for(const id of ['playerName','saveName','newGame']){const e=document.getElementById(id);if(e)e.disabled=true;}const original=document.getElementById('exportSave');if(original)original.textContent='Eksporter urørt original';}
panel.addEventListener('input',e=>{if(e.target.id==='ob-alias')ui.alias=e.target.value;if(e.target.id==='ob-sound')ui.sound=e.target.checked;});
panel.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;ui.error='';if(b.dataset.obGoal){ui.goal=b.dataset.obGoal;draw('[data-ob-goal="'+ui.goal+'"]');return;}switch(b.dataset.ob){case'next':ui.alias=alias(ui.alias);ui.step=1;draw();break;case'back':ui.step=0;draw();break;case'skip':start(true);break;case'start':start();break;case'export':exportOriginal();break;case'settings':recoverySettings();break;case'reload':root.location.reload();break;case'replace':if(root.confirm('Starte en ny runde? Den lokale originalen blir først erstattet når du bekrefter starten. Last ned originalfilen først hvis du vil beholde den.')){ui.replace=true;ui.mode='intro';draw();}break;}});
// Recovery uses the familiar import dialog, while preventing its name-save or
// fresh in-memory export from silently replacing the damaged original.
document.addEventListener('click',e=>{if(!panel.isConnected||ui.mode!=='recovery')return;const b=e.target.closest('button');if(!b||panel.contains(b))return;if(b.id==='exportSave'){e.preventDefault();e.stopImmediatePropagation();exportOriginal();}if(['saveName','newGame','confirmNew','confirmCampaign'].includes(b.id)){e.preventDefault();e.stopImmediatePropagation();}},true);
document.addEventListener('change',async e=>{if(!panel.isConnected||ui.mode!=='recovery'||e.target.id!=='importSave')return;e.stopImmediatePropagation();const file=e.target.files?.[0];if(!file)return;try{const raw=await file.text(),checked=classifyRaw(raw,game);if(checked.kind!=='valid')throw Error();const next=game.upgrade(checked.state);if(storage.getItem(STORE)!==originalRaw)throw Error();storage.setItem(STORE,JSON.stringify(next));s=next;view='home';document.querySelector('#dialog')?.close();close();render();toast('Sikkerhetskopien er importert.');}catch(_){toast('Filen kunne ikke importeres. Den eksisterende originalen er fortsatt bevart.');}},true);
document.addEventListener('keydown',e=>{if(!panel.isConnected||document.querySelector('#dialog')?.open)return;if(e.key==='Tab'){const nodes=[...panel.querySelectorAll('button:not([disabled]),input:not([disabled]),a[href]:not([tabindex="-1"])')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(e.key==='Enter'&&e.target.id==='ob-alias'){e.preventDefault();ui.alias=alias(ui.alias);ui.step=1;draw();}if(e.key==='Escape'){e.preventDefault();if(ui.mode==='intro'&&ui.step===1){ui.step=0;draw();}}});
draw();
})(typeof window!=='undefined'?window:globalThis);
